public class BatchConsumer {

    public static final String CONSUMER_GROUP = "gid-xiaozou-batch";

    public static final String TOPIC = "xiaozou-batch-topic";

    public static void main(String[] args) throws Exception {

        System.setProperty("rocketmq.namesrv.domain", "mqcloud-cider-dev.hishopcider.com:80");
        System.setProperty("rocketmq.namesrv.domain.subgroup", "nsaddr-2");

        DefaultMQPushConsumer consumer = new DefaultMQPushConsumer(CONSUMER_GROUP);
        consumer.setConsumeMessageBatchMaxSize(32); // 设置批量消费最大消息数
        consumer.subscribe(TOPIC, "*");
        consumer.registerMessageListener((MessageListenerConcurrently) (msgs, context) -> {
            // 批量处理消息
            for (MessageExt msg : msgs) {
                // 处理单条消息
                System.out.println("messageId" + msg.getMsgId() + "接受到的消息body: " + new String(msg.getBody()));
            }
            System.out.println("一批消息消费完成");
            return ConsumeConcurrentlyStatus.CONSUME_SUCCESS;
        });

        consumer.start();
        System.out.printf("Consumer Started.%n");
    }
}

