@GetMapping("/productManualCache")
public List<StudentVO> productManualCache(String name) {
    CiderCache cache = cacheManager.getCache(MyCiderCacheDataRegistered.PRODUCT_MANUAL_CACHE);
    List<StudentVO> list = cache.get(name, List.class);
    if (Objects.nonNull(list)) {
        return list;
    }
    List<StudentVO> vos = mockSelectSql();
    cache.put(name, vos);
    return vos;
}

