private BigDecimal reduceShippingFee(BigDecimal shippingFee, BigDecimal total) {

    while (shippingFee.compareTo(total) >= 0) {

        shippingFee = shippingFee.divide(BigDecimalUtils.TWO, 2, RoundingMode.DOWN);

    }

